def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    prev_bids = []
    opp_pressure = 0.0
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                bid = float(prev['bid'])
                prev_bids.append(bid)
                if bid > opp_pressure:
                    opp_pressure = bid

    if not alive_opponents:
        if hp <= 2 or no_water_days >= 1:
            return float(min(budget, DAILY_SALARY * 0.7))
        return float(min(budget, DAILY_SALARY * 0.25))

    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    if scarcity < 0:
        scarcity = 0.0
    if scarcity > 1:
        scarcity = 1.0

    danger = 0.0
    if hp <= 2:
        danger += 0.55
    elif hp <= 4:
        danger += 0.3
    if no_water_days >= 2:
        danger += 0.35
    elif no_water_days >= 1:
        danger += 0.18

    avg_prev = 0.0
    if prev_bids:
        avg_prev = sum(prev_bids) / float(len(prev_bids))

    live_count = len(alive_opponents)
    competitive_load = 0.08 * live_count

    base = DAILY_SALARY * (0.22 + 0.42 * scarcity + danger + competitive_load)

    if opp_pressure > 0:
        if scarcity >= 0.7 or danger >= 0.45:
            target = max(base, opp_pressure + 2.5)
        elif scarcity <= 0.25 and danger < 0.2:
            target = min(base, max(12.0, avg_prev * 0.45))
        else:
            target = max(base, avg_prev * 0.78)
    else:
        target = base

    if supply >= 23 and hp > 4 and no_water_days == 0:
        target *= 0.72
    elif supply <= 17:
        target *= 1.18

    if hp <= 2 or no_water_days >= 2:
        target = max(target, DAILY_SALARY * 0.92)
    elif hp <= 4 or no_water_days >= 1:
        target = max(target, DAILY_SALARY * 0.72)

    if day >= 8 and budget > DAILY_SALARY * 2:
        target *= 1.08

    max_safe = budget
    if day < 4:
        max_safe = min(max_safe, DAILY_SALARY * 1.15)
    else:
        max_safe = min(max_safe, budget)

    bid = min(max_safe, target)
    if bid < 0:
        bid = 0.0
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    # Alive opponents and their yesterday bids
    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append(o)

    # If we have no opponents (unlikely), bid conservatively
    if not alive_opps:
        return max(0.0, min(my_status['budget'], DAILY_SALARY * 0.4))

    yesterday_bids = []
    yesterday_pressures = []
    for o in alive_opps:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                yesterday_bids.append(float(b))
            except Exception:
                pass
        # Use hp_after/status as a crude pressure indicator
        hp_after = prev.get('hp_after', None)
        status = prev.get('status', None)
        if status in ('dead', 'eliminated') or (hp_after is not None and float(hp_after) <= 0):
            yesterday_pressures.append(1)

    # Determine competitive pressure from yesterday
    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0
    second_prev_bid = 0.0
    if len(yesterday_bids) >= 2:
        sorted_b = sorted(yesterday_bids, reverse=True)
        second_prev_bid = sorted_b[1]

    # Base bid target: aim to beat the likely clearing price without matching Cindy/David extremes
    # Approximate clearing price as slightly above the second-highest yesterday bid.
    # Add a small premium only if we are in danger.
    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    # Urgency factor
    urgency = 0.0
    if hp <= 2.0:
        urgency = 1.0
    elif hp <= 4.0:
        urgency = 0.6
    else:
        urgency = 0.3

    if no_water_days >= 2:
        urgency = max(urgency, 0.8)

    # Supply-based scaling: higher supply reduces need to overbid
    if supply >= 22.0:
        supply_factor = 0.85
    elif supply <= 17.0:
        supply_factor = 1.05
    else:
        supply_factor = 1.0

    # Compute candidate bid
    # If yesterday had very high bids (Cindy/David), we don't chase the max; we bid near the middle.
    chase_threshold = DAILY_SALARY * 1.2  # 108
    if highest_prev_bid >= chase_threshold:
        # competitive environment: bid around second-highest + premium
        premium = 6.0 + 10.0 * urgency
        target = second_prev_bid + premium
    else:
        # moderate environment: bid around highest_prev_bid with smaller premium
        premium = 4.0 + 8.0 * urgency
        target = highest_prev_bid + premium

    target *= supply_factor

    # Also ensure we don't bid beyond what we can afford
    # Keep a floor to avoid zeroing out when urgency is high.
    min_bid = 0.0
    if urgency >= 0.8:
        min_bid = DAILY_SALARY * 0.55
    elif urgency >= 0.6:
        min_bid = DAILY_SALARY * 0.45
    else:
        min_bid = DAILY_SALARY * 0.35

    bid = max(min_bid, target)
    bid = min(bid, budget)

    # If budget is extremely low, still bid something to prevent accumulating no_water_days
    if bid <= 0.0 and budget > 0.0:
        bid = min(budget, DAILY_SALARY * 0.2)

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10

    my_hp = my_status['hp']
    my_budget = my_status['budget']
    current_day = day_context['day']
    current_supply = day_context['supply']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive_opponents = len(alive_opponents)

    if num_alive_opponents == 0:
        return min(my_budget, DAILY_SALARY * 0.1)

    david_status = opponents_status.get('David')
    david_is_alive = david_status and david_status['alive']

    base_bid = DAILY_SALARY * 0.5

    if my_hp <= 2:
        base_bid = DAILY_SALARY * 0.9
    elif my_hp <= 4:
        base_bid = DAILY_SALARY * 0.75
    elif my_hp >= 8:
        base_bid = DAILY_SALARY * 0.4

    if current_day >= EPISODE_DAYS - 2 and my_hp < 5:
        base_bid = max(base_bid, DAILY_SALARY * 0.95)
    elif current_day >= EPISODE_DAYS - 4 and my_hp < 3:
        base_bid = max(base_bid, DAILY_SALARY * 0.9)

    if david_is_alive:
        david_previous_bid = 0
        if david_status.get('previous_trace') and david_status['previous_trace'].get('bid') is not None:
            david_previous_bid = david_status['previous_trace']['bid']

        if david_previous_bid > DAILY_SALARY * 0.6:
            base_bid = max(base_bid, david_previous_bid + (DAILY_SALARY * 0.05))
            base_bid = min(base_bid, DAILY_SALARY * 0.95)

    else:
        highest_other_prev_bid = 0
        for opp in alive_opponents:
            if opp['agent_id'] != 'David':
                prev = opp.get('previous_trace', {})
                if prev and prev.get('bid') is not None:
                    highest_other_prev_bid = max(highest_other_prev_bid, prev['bid'])

        if highest_other_prev_bid > 0:
            base_bid = max(base_bid, highest_other_prev_bid + (DAILY_SALARY * 0.05))
            base_bid = min(base_bid, DAILY_SALARY * 0.6)

    final_bid = max(0.0, min(my_budget, base_bid))

    if my_hp <= 1 and my_budget > 0:
        final_bid = my_budget

    total_water_needed_by_alive = sum([o['water_requirement'] for o in alive_opponents]) + WATER_REQ
    if current_supply >= total_water_needed_by_alive * 1.5 and num_alive_opponents < 3:
        final_bid = min(final_bid, DAILY_SALARY * 0.3)

    if final_bid == 0 and my_hp < 10 and my_budget > 0:
        final_bid = min(my_budget, DAILY_SALARY * 0.1)

    return final_bid
